<script setup>
import {computed,ref} from 'vue'
import {useRoute} from 'vue-router'
import {markets,path,fmt} from '../data'
import {session,openModal} from '../session'
import Coin from '../components/Coin.vue'
import Icon from '../components/Icon.vue'
const route=useRoute(),account=ref('資金帳戶'),hidden=ref(false),currency=ref('USDT'),from=ref('資金帳戶'),to=ref('交易帳戶'),amount=ref(''),message=ref('')
const section=computed(()=>route.params.section||''),balance=computed(()=>session.mode==='模擬'?100000:0)
function transfer(){message.value='';if(from.value===to.value){message.value='轉出與轉入帳戶不能相同';return}if(!Number(amount.value)||Number(amount.value)<=0){message.value='請輸入有效金額';return}if(Number(amount.value)>balance.value){message.value='可用餘額不足，請切換模擬帳戶體驗';return}session.orders.push({name:`劃轉：${from.value} → ${to.value}`,amount:amount.value,symbol:currency.value});amount.value='';message.value='演示劃轉已完成，已加入記錄。'}
</script>
<template><div class="page-wrap assets-page"><template v-if="!section"><div class="setup-banner"><strong>{{ $tr("完成帳戶設定 ") }}<span class="positive">1/3</span></strong><span>{{ $tr("✓ 建立帳戶") }}</span><RouterLink :to="path('/kyc')">{{ $tr("② 完成身分驗證") }}</RouterLink><span>{{ $tr("③ 完成首次充值") }}</span><RouterLink class="primary-button" :to="path('/deposit')">{{ $tr("立即充值 →") }}</RouterLink></div><section class="card account-overview"><div class="summary-line"><span>{{ $tr("總資產估值 ") }}<button class="icon-button" :aria-label="$tr(&quot;顯示或隱藏資產&quot;)" :aria-pressed="hidden" @click="hidden=!hidden">◉</button></span><span class="tag-chip">{{ $tr(session.mode) }}{{ $tr("帳戶") }}</span></div><div class="asset-total">{{ $tr(hidden?'••••••':fmt(balance)) }}<small>{{ $tr(" .00 USD") }}</small></div><div class="asset-actions"><RouterLink :to="path('/deposit')"><Icon name="wallet" green/>{{ $tr("充值") }}</RouterLink><RouterLink :to="path('/withdraw')"><Icon name="arrow-right"/>{{ $tr("提現") }}</RouterLink><button @click="openModal('convert','閃兌',{symbol:'USD',name:'USD → USDT',min:1})"><Icon name="coins"/>{{ $tr("閃兌") }}</button><RouterLink :to="path('/assets/transfer')"><Icon name="trending-up-down"/>{{ $tr("劃轉") }}</RouterLink><RouterLink :to="path('/assets/records')"><Icon name="layers"/>{{ $tr("記錄") }}</RouterLink></div></section><div class="asset-grid"><aside class="card"><div class="summary-line"><h2 style="font-size:1.125rem">{{ $tr("資產分佈") }}</h2><span class="mini-label">{{ $tr("USD") }}</span></div><div class="asset-distribution"><div class="donut"><strong>{{ $tr(hidden?'••••':fmt(balance)) }}</strong><span class="mini-label">{{ $tr("總資產估值") }}</span></div></div><div class="summary-line"><span class="muted">{{ $tr("今日盈虧") }}</span><span class="positive">0.00 (0.00%)</span></div><div class="section-gap"><button v-for="a in ['資金帳戶','交易帳戶','理財帳戶','量化基金帳戶']" :key="a" class="asset-account-button" :class="{active:account===a}" @click="account=a"><span>{{ $tr(a) }}</span><span>{{ $tr(hidden?'••••':a==='資金帳戶'?fmt(balance):'0.00') }} <small>{{ $tr("USD") }}</small></span></button></div></aside><section class="card"><div class="summary-line"><h2 style="font-size:1.125rem">{{ $tr(account) }}{{ $tr("明細") }}</h2><span class="mini-label">{{ $tr("資產 / 可用餘額") }}</span></div><div v-for="m in [...markets.filter(m=>['BTC','ETH','SOL','XRP'].includes(m.symbol)),{symbol:'USDT'},{symbol:'USDC'},{symbol:'DAI'},{symbol:'USD'}]" :key="m.symbol" class="asset-coin"><span class="coin-label"><Coin :symbol="m.symbol"/>{{ $tr(m.symbol) }}</span><span>{{ $tr(hidden?'••••':m.symbol==='USD'&&account==='資金帳戶'?fmt(balance):'0.00') }}<small class="mini-label">≈ {{ $tr(hidden?'••••':'0.00') }}{{ $tr(" USD") }}</small></span></div></section></div></template><template v-else-if="section==='transfer'"><div class="form-page"><RouterLink :to="path('/assets')" class="muted">{{ $tr("← 返回資產") }}</RouterLink><h1>{{ $tr("劃轉") }}</h1><form class="card form-stack" @submit.prevent="transfer"><label>{{ $tr("幣種") }}<select v-model="currency"><option :value="&quot;USDT&quot;">{{ $tr("USDT") }}</option><option :value="&quot;USD&quot;">{{ $tr("USD") }}</option><option :value="&quot;BTC&quot;">{{ $tr("BTC") }}</option><option :value="&quot;ETH&quot;">{{ $tr("ETH") }}</option></select></label><label>{{ $tr("從") }}<select v-model="from"><option :value="&quot;資金帳戶&quot;">{{ $tr("資金帳戶") }}</option><option :value="&quot;交易帳戶&quot;">{{ $tr("交易帳戶") }}</option></select></label><button class="green-link" type="button" @click="[from,to]=[to,from]">{{ $tr("⇅ 交換方向") }}</button><label>{{ $tr("到") }}<select v-model="to"><option :value="&quot;交易帳戶&quot;">{{ $tr("交易帳戶") }}</option><option :value="&quot;資金帳戶&quot;">{{ $tr("資金帳戶") }}</option></select></label><label>{{ $tr("劃轉數量") }}<input v-model="amount" inputmode="decimal" :placeholder="$tr(&quot;請輸入數量&quot;)"/></label><div class="summary-line mini-label"><span>{{ $tr("可用 ") }}{{ $tr(fmt(balance)) }} {{ $tr(currency) }}</span><button type="button" class="green-link" @click="amount=String(balance)">{{ $tr("全部") }}</button></div><p v-if="message" role="status" :class="message.includes('完成')?'form-success':'form-error'">{{ $tr(message) }}</p><button class="primary-button">{{ $tr("確認劃轉") }}</button><p class="mini-label">{{ $tr("本地演示記錄，不執行真實資金劃轉。") }}</p></form></div></template><template v-else><RouterLink :to="path('/assets')" class="muted">{{ $tr("← 返回資產") }}</RouterLink><h1 class="page-title">{{ $tr("資產記錄") }}</h1><div class="card"><div class="record-tabs"><button class="active">{{ $tr("全部記錄") }}</button></div><div v-if="!session.orders.length" class="empty"><Icon name="layers"/>{{ $tr("暫無記錄") }}</div><div v-for="(o,i) in session.orders" :key="i" class="asset-coin"><span>{{ $tr(o.name) }}</span><span>{{ $tr(o.amount) }} {{ $tr(o.symbol) }}<small class="positive">{{ $tr("演示已完成") }}</small></span></div></div></template></div></template>
<style scoped>.donut{border:12px solid #ffffff0b;width:160px;height:160px;border-radius:50%;display:flex;flex-direction:column;justify-content:center;gap:10px}.donut strong{font-size:1.5rem}.asset-coin{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:20px 0;border-bottom:1px solid #ffffff0a}.asset-coin>span:last-child{text-align:right}.asset-coin small{display:block;margin-top:6px}.asset-account-button small{font-size:0.625rem;color:#fff6}
</style>
